        'approval',
        'manual_classification',
        'user_validation',
      ];
      const automatedModules = [
        'import',
        'ocr',
        'classification',
        'field_extraction',
        'table_extraction',
        'barcode_extraction',
        'export',
      ];

      if (interactiveModules.includes(stepName)) {
        return { type: 'interactive', expectsUserWaiting: true };
      } else if (automatedModules.includes(stepName)) {
        return { type: 'automated', expectsUserWaiting: false };
      } else {
        return { type: 'unknown', expectsUserWaiting: null };
      }
