    },

    startStatusTracking() {
      this.requestStartTime = Date.now();
      this.elapsedTime = 0;

      // Update elapsed time every 100ms for smooth animations
      this.animationInterval = setInterval(() => {
        if (this.requestStartTime) {
          const previousElapsed = this.elapsedTime;
          this.elapsedTime = Date.now() - this.requestStartTime;

          // Check for status transitions to trigger feedback
          const previousStatus = this.getCurrentStatus;
          const currentStatus = this.getCurrentStatus;

          if (previousStatus !== currentStatus && currentStatus === 'timeout') {
            this.detectServiceTimeout();
          }
        }
      }, 100);
    },

    stopStatusTracking() {
      if (this.animationInterval) {
        clearInterval(this.animationInterval);
        this.animationInterval = null;
      }
      this.requestStartTime = null;
      this.elapsedTime = 0;
    },

    getCardStatusClass() {
      if (this.currentCard.action == 'restarted') return 'restarted';
      if (this.currentCard.action == 'export') return 'success-actions';
      if (this.currentCard.success == true)
        return 'process-steps completed-section';
      return this.getCurrentStatus;
    },

    getStatusBadgeClass() {
      if (this.isCompleted) return 'badge-completed';
      if (this.isProcessing) return 'badge-processing';
      if (this.isStarting) return 'badge-starting';
      return 'badge-waiting';
    },

    getStatusText() {
      if (this.isCompleted) return 'COMPLETE';
      if (this.isProcessing) return 'PROCESSING';
      if (this.isStarting) return 'STARTING';
      if (this.isWaiting) return 'IN QUEUE'; // More descriptive than "WAITING"
      return 'READY';
    },

    getAnimationClass() {
      if (!this.isProcessing) return '';
      return `status-${this.getCurrentStatus}`;
    },

    getCardStyle() {
      const status = this.getCurrentStatus;
      const borderColors = {
        waiting: '#9e9e9e', // Gray
        starting: '#ff9800', // Orange (indicating ready to start)
        idle: '#e0e0e0',
        processing: '#4caf50', // Green
        delayed: '#ff9800', // Orange
        timeout: '#f44336', // Red
        completed: '#2196f3', // Blue
      };

      return {
        borderColor: borderColors[status] || borderColors.idle,
        transition: 'border-color 0.5s ease-in-out',
      };
    },

    getProgressStyle() {
      const progress = Math.min(
        (this.elapsedTime / this.getExpectedDuration) * 100,
