      };

      return {
        width: `${progress}%`,
        backgroundColor: progressColors[status] || progressColors.processing,
        transition: 'width 0.3s ease-out, background-color 0.5s ease-in-out',
      };
    },

    getProgressText() {
      const progress = Math.min(
        (this.elapsedTime / this.getExpectedDuration) * 100,
        100,
      );
      const status = this.getCurrentStatus;

      const statusTexts = {
        processing: this.$t ? this.$t('service_processing') : 'Processing...',
        delayed: this.$t ? this.$t('service_delayed') : 'Taking longer...',
        timeout: this.$t ? this.$t('service_timeout') : 'Timeout warning',
      };

      return `${statusTexts[status]} (${Math.round(progress)}%)`;
