            </div>

            <!-- Calculate time delta from timestamps if restart_delta_seconds not available -->
            <div
              class="timestamp-item"
              v-else-if="selectedCard.started_at && selectedCard.completed_at"
            >
              <div class="timestamp-label">Time Delta</div>
              <div
                class="timestamp-value"
                :class="getCalculatedTimeDeltaClass(selectedCard)"
              >
                {{ calculateTimeDeltaFromTimestamps(selectedCard) }}
