<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';

import { documentFlowDataService, genericService } from 'src/services';
import type {
  ClearFlowUntilRestartResponse,
  ClearFlowErrorResponse,
} from 'src/services/document/FlowDataService';
import DocumentFlowCard from './DocumentFlowCard.vue';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
// TypeScript interfaces for log data structure
interface TaskLogEntry {
  timestamp: string;
  level: string;
  message: string;
  logger_name?: string;
  thread_name?: string;
  process_id?: number;
}

interface TaskLogsResponse {
  logs: TaskLogEntry[];
  total_entries: number;
  has_more: boolean;
}

export default defineComponent({
  el: '#app',
    components: {
    
    SubHeader,
    DocumentFlowCard,
  },
  props: {
    doc_id: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      instance: null,
      prevRoute: '/dashboard' as any,
      previousPageName: 'dashboard',
      cardsPerRow: 3, // 🎯 UX IMPROVEMENT: 3 cards per row for optimal spacing and readability
      connectorStyles: [],
      snakedRows: [] as any[],
      clearingFlow: false,
      selectedCard: null as any, // Store selected card for details panel
      pollTimeoutId: null as any, // 🎯 UX FIX: Track polling timeout for cleanup
    };
  },
  mounted() {
    this.init();
    document.addEventListener('keydown', this.sendBack);
    document.addEventListener('click', this.handleClickOutside);
    this.prevRoute = this.$router.options.history.state.back ?? '/dashboard';
    if (this.prevRoute.includes('field_validation_v1')) {
      this.previousPageName = 'field_validation';
    }

    // Set up polling for missing task IDs
    this.setupTaskIdPolling();
  },
  unmounted() {
    document.removeEventListener('keydown', this.sendBack);
    document.removeEventListener('click', this.handleClickOutside);

    // 🎯 CRITICAL UX FIX: Clean up polling to prevent reload issues
    if (this.pollTimeoutId) {
      clearTimeout(this.pollTimeoutId);
      this.pollTimeoutId = null;
    }
  },

  computed: {
    processStats() {
      const stats = {
        totalSteps: this.elements.length,
        completedSteps: 0,
        runningSteps: 0,
        waitingSteps: 0,
        restartCount: 0,
        totalProcessingTime: '0s',
        overallStatus: 'WAITING',
      };

      let totalTime = 0;
      let hasRunning = false;
      let hasWaiting = false;

      this.elements.forEach((element: any) => {
        // Count step statuses
        if (element.success === true) {
          stats.completedSteps++;
        } else if (element.action === 'running') {
          stats.runningSteps++;
          hasRunning = true;
        } else if (element.action === 'starting') {
          stats.runningSteps++;
          hasRunning = true;
        } else {
          stats.waitingSteps++;
          hasWaiting = true;
        }

        // Count restarts
        if (element.action === 'restarted' || element.name === 'restarted') {
          stats.restartCount++;
        }

        // Calculate total time
        if (element.time && element.time !== '-') {
          const timeValue = parseFloat(
            element.time.toString().replace(/[^\d.]/g, ''),
          );
          if (!isNaN(timeValue)) {
            totalTime += timeValue;
          }
        }
      });

      // Format total time
      if (totalTime > 0) {
        stats.totalProcessingTime = totalTime.toFixed(1) + 's';
      } else {
        stats.totalProcessingTime = '-';
      }

      // Determine overall status
      if (hasRunning) {
        stats.overallStatus = 'PROCESSING';
      } else if (stats.completedSteps > 0 && !hasWaiting) {
        stats.overallStatus = 'COMPLETED';
      } else if (hasWaiting) {
        stats.overallStatus = 'WAITING';
      }

      return stats;
    },

    getProgressPercentage() {
      if (this.processStats.totalSteps === 0) return 0;
      return Math.round(
        (this.processStats.completedSteps / this.processStats.totalSteps) * 100,
      );
    },

    getEstimatedCompletion() {
      const runningSteps = this.processStats.runningSteps;
      const waitingSteps = this.processStats.waitingSteps;

      if (runningSteps === 0 && waitingSteps === 0) return null;

      // Rough estimation: 4 seconds per remaining step
      const remainingSteps = runningSteps + waitingSteps;
      const estimatedSeconds = remainingSteps * 4;

      if (estimatedSeconds < 60) {
        return `~${estimatedSeconds}s`;
      } else {
        return `~${Math.round(estimatedSeconds / 60)}m`;
      }
    },

    rowConnectors() {
      const connectors = [];
      const cardWidth = 180;
      const cardGap = 1;
      const rowHeight = 170; // 🎯 UX FIX: Fixed height for professional card layout

      // Calculate connectors for each end-of-row transition
      for (let i = 0; i < this.elements.length; i++) {
        const isEndOfRow = (i + 1) % this.cardsPerRow === 0;
        const isNotLastElement = i < this.elements.length - 1;

        if (
          isEndOfRow &&
          isNotLastElement &&
          this.elements[i].type !== 'placeholder'
        ) {
          const currentRow = Math.floor(i / this.cardsPerRow);
          const currentCol = i % this.cardsPerRow;

          // Calculate exact positions
          const startX = currentCol * (cardWidth + cardGap) + cardWidth / 2; // Center of current card
          const startY = currentRow * rowHeight + 120; // 🎯 UX FIX: Bottom of current card - professional spacing
          const endX = cardWidth / 2; // Center of first card in next row
          const endY = (currentRow + 1) * rowHeight; // Top of next row

          connectors.push({
            id: `connector-${i}-to-${i + 1}`,
            type: 'l-shaped',
            style: {
              position: 'absolute',
              left: startX + 'px',
              top: startY + 'px',
              width: '1px',
              height: '60px',
              backgroundColor: '#e2e8f0',
              zIndex: 1,

              // CSS custom properties for pseudo-element positioning
              '--start-x': startX + 'px',
              '--start-y': startY + 'px',
              '--end-x': endX + 'px',
              '--end-y': endY + 'px',
              '--span-width': startX - endX + 'px',
            },
          });
        }
      }

      return connectors;
    },
  },

  methods: {
    // 🎯 CARD INTERACTION METHODS
    handleCardClick(card: any) {
      if (this.selectedCard && this.selectedCard.id === card.id) {
        // If clicking the same card, close both panels
        this.selectedCard = null;
        this.showLogsPanel = false;
      } else {
        // Select the new card and show logs panel
        this.selectedCard = card;
        this.showLogsPanel = true;
        this.loadTaskLogs(card);
      }
    },

    closeDetailsPanel() {
      this.selectedCard = null;
      this.showLogsPanel = false;
    },

    async loadTaskLogs(card: any) {
      if (!card.celery_task_id || card.celery_task_id === '-') {
        this.taskLogs = [];
        return;
      }

      this.logsLoading = true;

      try {
        // TODO: Fix logs endpoint - currently incorrect
        // const logLevels = 'ERROR,WARN,INFO,DEBUG';
        // const url = `${process.env.VITE_APP_VUE_DOC2_SERVICE_URL}/api/docflow/${this.docID}/task/${card.celery_task_id}/logs?log_level=${logLevels}&limit=100`;
        // const response = await genericService.get(url) as { data: TaskLogsResponse };

        // Temporary: Return empty logs until correct endpoint is implemented
        const response = { data: { logs: [], total_entries: 0 } };

        this.taskLogs = response.data.logs || [];

        // Sort logs by timestamp (newest first)
        this.taskLogs.sort(
          (a: TaskLogEntry, b: TaskLogEntry) =>
            new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
        );

        notify.success(`Loaded ${response.data.total_entries || 0} log entries`);
      } catch (error) {
        console.error('Failed to load task logs:', error);
        this.taskLogs = [];

        notify.warning('Logs not available yet - task may still be starting', { duration: 3000 });
      } finally {
        this.logsLoading = false;
      }
    },

    // Helper methods for enhanced logs panel
    getLogEndpoint() {
      if (
        !this.selectedCard?.celery_task_id ||
        this.selectedCard.celery_task_id === '-'
      ) {
        return 'Task ID not available';
      }
      // TODO: Fix logs endpoint - currently incorrect
      // return `${process.env.VITE_APP_VUE_DOC2_SERVICE_URL}/api/docflow/${this.docID}/task/${this.selectedCard.celery_task_id}/logs`;
      return 'Logs endpoint temporarily disabled - incorrect API endpoint';
    },

    getLastUpdateTime() {
      if (this.taskLogs.length === 0) return '-';
      const latestLog: TaskLogEntry = this.taskLogs[0];
      return this.formatLogTimestamp(latestLog.timestamp);
    },

    formatLogTimestamp(timestamp: string) {
      if (!timestamp) return '-';
      try {
        const date = new Date(timestamp);
        return date.toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
          hour12: false,
        });
      } catch (error) {
        return timestamp;
      }
    },

    formatLogMessage(message: string) {
      if (!message) return '';

      // Highlight important keywords
      return message
        .replace(
          /(ERROR|CRITICAL|FATAL)/gi,
          '<span class="log-error-keyword">$1</span>',
        )
        .replace(
          /(WARNING|WARN)/gi,
          '<span class="log-warning-keyword">$1</span>',
        )
        .replace(
          /(SUCCESS|COMPLETED|FINISHED)/gi,
          '<span class="log-success-keyword">$1</span>',
        )
        .replace(/(INFO|DEBUG)/gi, '<span class="log-info-keyword">$1</span>');
    },

    getLogEntryClass(log: TaskLogEntry) {
      const level = log.level?.toUpperCase();
      return {
        'log-error':
          level === 'ERROR' || level === 'CRITICAL' || level === 'FATAL',
        'log-warning': level === 'WARNING' || level === 'WARN',
        'log-info': level === 'INFO',
        'log-debug': level === 'DEBUG',
      };
    },

    getLogLevelClass(level: string) {
      const upperLevel = level?.toUpperCase();
      return {
        'level-error':
          upperLevel === 'ERROR' ||
          upperLevel === 'CRITICAL' ||
          upperLevel === 'FATAL',
        'level-warning': upperLevel === 'WARNING' || upperLevel === 'WARN',
        'level-info': upperLevel === 'INFO',
        'level-debug': upperLevel === 'DEBUG',
        'level-success': upperLevel === 'SUCCESS',
      };
    },

    getLogLevelIcon(level: string) {
      const upperLevel = level?.toUpperCase();
      switch (upperLevel) {
        case 'ERROR':
        case 'CRITICAL':
        case 'FATAL':
          return 'error';
        case 'WARNING':
        case 'WARN':
          return 'warning';
        case 'INFO':
          return 'info';
        case 'DEBUG':
          return 'bug_report';
        case 'SUCCESS':
          return 'check_circle';
        default:
          return 'radio_button_unchecked';
      }
    },

    handleClickOutside(event: Event) {
      if (!this.selectedCard) return;

      const detailsPanel = document.querySelector('.details-panel');
      const target = event.target as HTMLElement;

      // If clicking outside the details panel and not on a card
      if (
        detailsPanel &&
        !detailsPanel.contains(target) &&
        !target.closest('.card')
      ) {
        this.selectedCard = null;
      }
    },

    copyTaskID(taskId: string) {
      navigator.clipboard.writeText(taskId);
      notify.success('Task ID copied to clipboard');
    },

    // 🎯 DETAILS PANEL HELPER METHODS
    getDetailStatusText(card: any) {
      if (card.success === true) return 'Completed';
      if (card.action === 'running') return 'Processing';
      if (card.action === 'starting') return 'Starting';
      if (card.action === 'restarted') return 'Restarted';
      return 'Queued';
    },

    getDetailStatusClass(card: any) {
      if (card.success === true) return 'detail-status-completed';
      if (card.action === 'running') return 'detail-status-processing';
      if (card.action === 'starting') return 'detail-status-starting';
      if (card.action === 'restarted') return 'detail-status-restarted';
      return 'detail-status-queued';
    },

    hasDetailedTiming(card: any) {
      return (
        !!(
          card.queue_waiting_time !== null &&
          card.queue_waiting_time !== undefined
        ) ||
        !!(
          card.actual_processing_time !== null &&
          card.actual_processing_time !== undefined
        ) ||
        !!(
          card.user_waiting_time !== null &&
          card.user_waiting_time !== undefined
        )
      );
    },

    hasTimestamps(card: any) {
      return !!(
        card.started_at ||
        card.completed_at ||
        card.created_at ||
        (card.restart_delta_seconds !== null &&
          card.restart_delta_seconds !== undefined)
      );
    },

    formatDetailTime(seconds: number) {
      if (seconds === null || seconds === undefined) return '-';
      if (typeof seconds === 'number') {
        return seconds.toFixed(1) + 's';
      }
      return String(seconds);
    },

    calculateTotalTime(card: any) {
      if (!card) return '-';

      const queueTime = card.queue_waiting_time || 0;
      const processingTime = card.actual_processing_time || 0;
      const userTime = card.user_waiting_time || 0;

      // Calculate total time = Queue Waiting + Processing Time + User Waiting
      const total = queueTime + processingTime + userTime;

      if (total > 0) {
        return total.toFixed(1) + 's';
      }

      return '-';
    },

    formatTimestamp(timestamp: string) {
      if (!timestamp) return '-';
      try {
        const cleanTimestamp = this.cleanTimestamp(timestamp);
        const date = new Date(cleanTimestamp);

        // Check if date is valid
        if (isNaN(date.getTime())) {
          console.warn('Invalid timestamp:', timestamp);
          return 'Invalid Date';
        }

        return date.toLocaleString([], {
          year: 'numeric',
          month: 'short',
          day: 'numeric',
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
        });
      } catch (error) {
        console.error('Error parsing timestamp:', timestamp, error);
        return 'Invalid Date';
      }
    },

    formatTimeDelta(deltaSeconds: number) {
      if (deltaSeconds === null || deltaSeconds === undefined) return '-';
      if (typeof deltaSeconds !== 'number') return '-';
      const sign = deltaSeconds >= 0 ? '+' : '';
      return `${sign}${deltaSeconds.toFixed(1)}s`;
    },

    getTimeDeltaClass(delta: number) {
      if (delta === null || delta === undefined || typeof delta !== 'number') {
        return 'delta-unknown';
      }
      if (delta <= 10) return 'delta-immediate';
      if (delta <= 60) return 'delta-normal';
      return 'delta-delayed';
    },

    getSLAStatusText(card: any) {
      // Simplified SLA status for details panel
      if (card.success === true) return 'Met';
      if (card.action === 'running') return 'On Track';
      return 'Pending';
    },

    getSLAStatusClass(card: any) {
      if (card.success === true) return 'sla-met';
      if (card.action === 'running') return 'sla-on-track';
      return 'sla-pending';
    },

    calculateTimeDeltaFromTimestamps(card: any) {
      if (!card.started_at || !card.completed_at) return '-';

      try {
        // Clean timestamps to handle the trailing Z issue
        const cleanStartTime = this.cleanTimestamp(card.started_at);
        const cleanEndTime = this.cleanTimestamp(card.completed_at);

        // Create Date objects
        const startDate = new Date(cleanStartTime);
        const endDate = new Date(cleanEndTime);

        // Validate timestamps
        if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
          console.warn('Invalid timestamps:', {
            started_at: card.started_at,
            completed_at: card.completed_at,
            cleanStartTime,
            cleanEndTime,
          });
          return 'Invalid';
        }

        // Calculate time difference in milliseconds
        const deltaMilliseconds = endDate.getTime() - startDate.getTime();
        const deltaSeconds = deltaMilliseconds / 1000;

        // Debug logging for verification
        console.debug('Time delta calculation:', {
          started_at: card.started_at,
          completed_at: card.completed_at,
          startDate: startDate.toISOString(),
          endDate: endDate.toISOString(),
          deltaMilliseconds,
          deltaSeconds,
        });

        // Format with appropriate precision
        const sign = deltaSeconds >= 0 ? '+' : '';
        const formattedDelta =
          Math.abs(deltaSeconds) < 0.1
            ? deltaSeconds.toFixed(3) // Higher precision for very small deltas
            : deltaSeconds.toFixed(1); // Standard precision

        return `${sign}${formattedDelta}s`;
      } catch (error) {
        console.error('Error calculating time delta:', error);
        return 'Error';
      }
    },

    getCalculatedTimeDeltaClass(card: any) {
      try {
        const cleanStartTime = this.cleanTimestamp(card.started_at);
        const cleanEndTime = this.cleanTimestamp(card.completed_at);

        const startDate = new Date(cleanStartTime);
        const endDate = new Date(cleanEndTime);

        if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
          return 'delta-unknown';
        }

        const deltaMilliseconds = endDate.getTime() - startDate.getTime();
        const deltaSeconds = deltaMilliseconds / 1000;

        return this.getTimeDeltaClass(deltaSeconds);
      } catch (error) {
        return 'delta-unknown';
      }
    },

    cleanTimestamp(timestamp: string) {
      if (!timestamp) return timestamp;

      // Handle the trailing 'Z' issue in timestamps like "2025-08-27T12:31:08.144619+00:00Z"
      let cleanTimestamp = timestamp;
      if (timestamp.endsWith('+00:00Z')) {
        // Remove the trailing Z as it's redundant with +00:00
        cleanTimestamp = timestamp.slice(0, -1);
      } else if (timestamp.includes('+00:00') && timestamp.endsWith('Z')) {
        // Handle any other cases where both timezone and Z are present
        cleanTimestamp = timestamp.replace('Z', '');
      }

      return cleanTimestamp;
    },

    async init() {
      await this.prepareFlowData();

      let org_color = this.user_settings['ORG_COLOR_PREFERENCE']
      if (!this.user_settings['ORG_COLOR_PREFERENCE']) {
        org_color = getComputedStyle(document.documentElement).getPropertyValue('--primary-color').trim()
      }
