    },
    goToDashboard() {
      this.$router.push(this.prevRoute);
    },
    generalizer(item: any) {
      item.origid = item.id;

      if (item.waiting_time == null || item.waiting_time == 0) {
        item.waiting_time = '-';
      } else {
        item.waiting_time = item.waiting_time.toFixed(2) + ' sec';
      }

      if (item.time && item.time != 0) {
        const [minutes, seconds] = item.time?.toString().split(':').map(Number);
        if (seconds > 0) {
          item.timeTaken = minutes * 60 + seconds + ' sec';
        } else {
          item.timeTaken = item.time.toString() + ' sec';
        }
      } else {
        item.timeTaken = '-';
      }

      item.id = this.elements.length.toString();
      const match = this.wordfilter.find((obj) => item.name in obj);
      if (match) {
        item.label = match[item.name];
      } else {
        item.label = this.$t(item.name);
      }

      if (
        !item.celery_task_id ||
        item.celery_task_id === '' ||
        item.celery_task_id === null
      ) {
        item.celery_task_id = '-';
        // Flag for potential refresh if this is a recent restart
        item.needs_task_id_refresh = true;
      } else {
        item.needs_task_id_refresh = false;
      }
      item.showIcon = true;
    },

    showLog_module(module: any) {
      this.logdata = [];
      if (module == '') {
        this.logdata = this.logtaildata;
      } else {
        Array.from(this.logtaildata).forEach((log: any) => {
          if (log.module == module) {
            this.logdata.push(log);
          }
        });
      }
    },
    showLog_level(level: any) {
      this.logdata = [];
      if (level == '') {
        this.logdata = this.logtaildata;
      } else {
        Array.from(this.logtaildata).forEach((log: any) => {
